  "rcloneRemote.heading": "Engadir un destino SMB ou WebDAV",
  "rcloneRemote.hint": "Accede a unha compartición de Windows ou Samba, ou a un servidor WebDAV como Nextcloud, sen montar nada no host. restic desaconsella gardar un repositorio nunha compartición CIFS montada, e esta vía evita a montaxe por completo. O contrasinal pásase a rclone, que o garda no seu propio formato, e nunca se almacena en claro. NFS non se ofrece aquí porque nin restic nin rclone o admiten: para NFS, monta a exportación en Unraid e apunta un camiño de copia cara a ela.",
