  "idle.toggle": "Agardar a que a app estea inactiva",
  "idle.toggleHint": "Unha copia programada deste contedor agarda mentres a app está ocupada e comeza cando queda inactiva, ou cando remata a espera. Un servidor multimedia está inactivo cando non fai streaming; calquera outra app, cando a CPU e o tráfico se manteñen baixos (Configuración, Horario). As copias manuais nunca agardan.",
