  // Off-site (rclone)
  "rclone.title": "Externa (rclone)",
  "rclone.hint": "Pega unha configuración rclone para facer copia na nube (Backblaze B2, S3, Google Drive, …). Gárdase cifrada. SMB/NFS non precisan rclone: monta a comparticón en Unraid e apunta un camiño de copia cara a ela.",
  "rclone.configured": "Remotos configurados",
  "rclone.pathHint": "Despois, configura un camiño de copia como «rclone:<remote>:<bucket>/camiño» para enviar esa sección á externa.",
  "cloud.title": "Credenciais de nube compartidas (S3 / restic REST)",
  "cloud.hint": "Credenciais para backends restic externos, sen rclone. Despois de gardar, configura un camiño de copia a un repositorio remoto, p. ex. s3:s3.amazonaws.com/bucket/camiño, rest:http://host:8000/repo ou sftp:user@host:/repo. Os segredos gárdanse cifrados e non se mostran de novo.",
  "cloud.secretSet": "gardado, déixao baleiro para conservalo",
  "cloud.storageClass.label": "Clase de almacenamento externo",
  "cloud.storageClass.default": "(por defecto do provedor)",
  "cloud.storageClass.hint": "Só se aplica a backends S3 nativos (repositorios que comezan por s3:). Os niveis de arquivo profundo (Glacier Flexible Retrieval, Deep Archive) non se ofrecen a propósito porque rompen a restauración de restic.",
  "cloud.credSets.title": "Conxuntos de credenciais adicionais",
  "cloud.credSets.hint": "Dálle a un ou máis destinos externos as súas propias credenciais S3 ou restic REST, en vez de compartir as de arriba.",
