  "notify.appriseTags": "Etiquetas (opcional)",
  "notify.appriseHint": "Apunta ao punto final /notify/<key> do teu contedor Apprise API para distribuír a máis de 100 dos seus servizos (Telegram, Pushover, Signal, …). As etiquetas encamiñan a un subconxunto dos destinos desta clave; déixao baleiro para todos.",
  "notify.matrix": "Matrix",
  "notify.matrixHomeserver": "URL do homeserver",
  "notify.matrixToken": "Testemuño de acceso",
  "notify.matrixRoom": "ID da sala",
  "notify.healthchecksTitle": "Healthchecks",
  "notify.healthchecks": "URL de ping",
  "notify.healthchecksLifecycle": "Faise ping a Healthchecks durante todo o ciclo de vida da copia (inicio, éxito e erro) sempre que haxa unha URL configurada, independentemente do axuste «notificar en» de arriba, así a comprobación queda verde en éxito mesmo con notificacións só de erro.",
  "notify.scheduledSummary": "Resumir as execucións programadas",
  "notify.scheduledSummaryHint": "Envía un resumo por cada execución de copia programada (p. ex. «42 de 45 correctas») en vez dunha mensaxe separada por cada contedor/MV. Healthchecks xa se resume. As copias manuais seguen notificando por elemento.",
  "notify.notifyOnUpdate": "Notificar ao actualizar un contedor",
  "notify.notifyOnUpdateHint": "Cando «actualizar despois da copia» sobe un contedor a unha imaxe máis nova, envía unha mensaxe para que poidas comprobar que aínda funciona. Dispárase por cada contedor actualizado (as actualizacións son raras).",
  "notify.unraid": "Notificacións de Unraid",
  "notify.unraidHint": "Envía ao propio sistema de notificacións de Unraid (que pode reenviar a Pushover, correo, Discord, …). Execútase a través da conexión SSH de Configuración, Integracións, SSH do host, así que a clave debe estar autorizada alí, pero libvirt/MV non son necesarios (ignora un resultado «libvirt not reachable» se non fas copia de MV). Usa Enviar proba abaixo para comprobalo.",
  "notify.unraidPlatformMismatch": "BombVault detectou este host como «{platform}», non como Unraid. As notificacións de Unraid quedan desactivadas mesmo con este interruptor activado. Se isto É un host Unraid, comproba que o /boot do host estea montado en /host/boot dentro do contedor (mira o modelo de Unraid de BombVault) e reinicia o contedor.",
  "notify.unraidOffOnPlatformSetting": "PLATFORM define este host como «{platform}», así que as notificacións de Unraid quedan desactivadas mesmo con este interruptor activado.",
  "notify.unraidOffOnTrueNAS": "Este host usa TrueNAS, así que as notificacións de Unraid quedan desactivadas mesmo con este interruptor activado.",
