  // Off-site DR opt-out
  "settings.offsiteDrills": "Proba DR externa programada",
  "settings.offsiteDrillsHelp": "Restaura a copia externa completa segundo o horario de probas para demostrar a recuperación remota. Isto volve descargar toda a copia en cada execución, o que ten un custo de saída en nubes con consumo medido (por exemplo Backblaze B2). Desactívao para conservar só a comprobación local gratuíta de integridade e executar a comprobación DR externa manualmente.",

  // Pre/post-backup hooks
  "hooks.hint": "As ordes execútanse dentro do contedor con sh -c. A orde previa execútase antes da copia; úsaa para preparar datos que deben copiarse, por exemplo volcando unha caché ao disco. As bases de datos recoñecidas vólcanse automaticamente e non precisan ningún gancho. Se a orde previa falla, a copia abórtase. A orde posterior execútase despois de que o contedor se inicie de novo e o seu erro só se rexistra. Os ganchos só executan ordes, non engaden cartafoles adicionais á copia.",
  "hooks.pre": "Orde previa á copia",
  "hooks.post": "Orde posterior á copia",
  "folders.title": "Cartafoles da copia",
  "folders.hint": "Escolle cales dos cartafoles mapeados deste contedor se copian. O cartafol appdata está seleccionado por defecto. Marca outros para incluílos, ou engade un camiño propio baixo a montaxe do host. Desmarcar todo está bloqueado; usa Restablecer selección para volver ao padrón automático de appdata.",
  "folders.appdataDefault": "appdata (por defecto)",
