  "recovery.abTitle": "Importar desde o complemento Appdata.Backup",
  "recovery.abIntro": "Converte os arquivos que escribiu o complemento Appdata.Backup en puntos de restauración dos contedores correspondentes, cada un coa data en que o complemento o creou. Os arquivos só se len, nunca se modifican nin se borran. Cada un descomprímese xunto ao repositorio, cópiase e a copia descomprimida bórrase de novo, así que alí fai falta espazo para o arquivo máis grande.",
