  "api.title": "Testemuños da API",
  "api.hint": "Testemuños para scripts, paneis e domótica. Un testemuño abre a API en /api/v1 e nada máis. As restauracións, os borrados e os axustes quedan nesta interface web.",
  "api.addressLabel": "Enderezo da API",
  "api.addressHint": "Envía o testemuño como Authorization: Bearer <token> ou na cabeceira X-API-Key. A descrición de todas as rutas está en /api/v1/openapi.json e non precisa testemuño.",
  "api.viewDescription": "Abrir a descrición",
  "api.noPasswordWarning": "Non hai contrasinal de acceso, así que esta interface web está aberta a todos na túa rede, e quen a poida abrir tamén pode crear un testemuño.",
  "api.needsPasswordForHost": "Esta páxina abriuse como {host}. Sen contrasinal de acceso, os testemuños só se poden crear e substituír desde un enderezo IP ou un nome local como tower ou tower.local. Define un contrasinal de acceso ou abre BombVault polo seu enderezo local.",
