  "ha.title": "Home Assistant",
  "ha.hint": "Envía o estado das copias a Home Assistant a través dun broker MQTT. BombVault aparece alí como un dispositivo con sensores e un botón de copia por sección. Apunta a integración MQTT de Home Assistant ao mesmo broker.",
  "ha.loadFailed": "Non se puideron cargar os axustes de Home Assistant",
